func (n *Node) Propose() (ProposalView, error) {
	n.mu.Lock()
	defer n.mu.Unlock()
	if n.st.Proposal != nil {
		return n.proposalView(n.st.Proposal), nil
	}

	txIDs := n.selectTransactions()
	height := uint64(len(n.st.Blocks)) + 1
	blockID := BlockID(n.st.Round, height, n.st.LastBlock, txIDs)
	p := &proposalState{
		Round:   n.st.Round,
		TxIDs:   txIDs,
		BlockID: blockID,
		Votes:   []string{},
	}
	n.st.Proposal = p
	for _, id := range txIDs {
		n.st.Entries[id].Status = stProposed
	}
	if err := n.save(n.st); err != nil {
		return ProposalView{}, err
	}
	return n.proposalView(p), nil
}

