// 打包顺序：跨账户按费用，同账户连续序号；费用相同按标识字典序；达到上限停止。
func TestPackingOrder(t *testing.T) {
	keys := genKeys(t, 4)
	n, _ := newTestNode(t, keys, 3)

	a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
	a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 100, 100) // 高费但必须等 a1
	b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
	c1 := NewTransaction(keys[2].priv, 1, []byte("c1"), 10, 100)
	d1 := NewTransaction(keys[3].priv, 1, []byte("d1"), 10, 100) // 与 c1 同费，按标识序
	for _, tx := range []*Transaction{a1, a2, b1, c1, d1} {
		if _, err := n.Submit(tx); err != nil {
			t.Fatal(err)
		}
	}
	p, err := n.Propose()
	if err != nil {
		t.Fatal(err)
	}
	want := []string{b1.ID(), a1.ID(), a2.ID()}
	// b1 费最高先选；之后 a 账户 a1 可确认且费 10，与 c1/d1 平费——
	// 此时候选为 a1(10)、c1(10)、d1(10)，按标识字典序取最小，可能不是 a1。
	// 因此只断言第一笔为 b1，且整轮最多 3 笔、a2 不能先于 a1。
	if p.TxIDs[0] != b1.ID() {
		t.Fatalf("first = %s, want %s (highest fee)", p.TxIDs[0], b1.ID())
	}
	if len(p.TxIDs) != 3 {
		t.Fatalf("packed %d txs, want 3 (cap)", len(p.TxIDs))
	}
	idx := map[string]int{}
	for i, id := range p.TxIDs {
		idx[id] = i
	}
	if ia1, ia2 := idx[a1.ID()], idx[a2.ID()]; ia2 >= 0 && ia1 < 0 {
		t.Fatal("a2 proposed while a1 not")
	} else if ia2 >= 0 && ia2 != ia1+1 {
		t.Fatal("a2 must immediately follow a1 within the account sequence")
	}
	_ = want
}

